(function(){var n=document.querySelectorAll(".faq-item");n.forEach(function(e){var t=e.querySelector(".faq-item__btn");t&&t.addEventListener("click",function(){var i=e.classList.contains("open");n.forEach(function(a){a.classList.remove("open");var r=a.querySelector(".faq-item__btn");r&&r.setAttribute("aria-expanded","false")}),i||(e.classList.add("open"),t.setAttribute("aria-expanded","true"))})})})();
